import{_ as r,o as a,c as t,al as o}from"./chunks/framework.7vp1BMOE.js";const c=JSON.parse('{"title":"비행 콘트롤러 포팅 가이드","description":"","frontmatter":{},"headers":[],"relativePath":"ko/hardware/porting_guide.md","filePath":"ko/hardware/porting_guide.md"}'),i={name:"ko/hardware/porting_guide.md"};function l(n,e,s,d,h,p){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="비행-콘트롤러-포팅-가이드" tabindex="-1">비행 콘트롤러 포팅 가이드 <a class="header-anchor" href="#비행-콘트롤러-포팅-가이드" aria-label="Permalink to &quot;비행 콘트롤러 포팅 가이드&quot;">​</a></h1><p>This topic is for developers who want to port PX4 to work with <em>new</em> flight controller hardware.</p><h2 id="px4-아키텍쳐" tabindex="-1">PX4 아키텍쳐 <a class="header-anchor" href="#px4-아키텍쳐" aria-label="Permalink to &quot;PX4 아키텍쳐&quot;">​</a></h2><p>PX4 consists of two main layers: The <a href="./../middleware/">board support and middleware layer</a> on top of the host OS (NuttX, Linux or any other POSIX platform like Mac OS), and the applications (Flight Stack in <a href="https://github.com/PX4/PX4-Autopilot/tree/main/src/modules" target="_blank" rel="noreferrer">src/modules</a>). Please reference the <a href="./../concept/architecture">PX4 Architectural Overview</a> for more information.</p><p>애플리케이션/플라이트 스택이 모든 보드 대상에서 실행되므로, 이 가이드에서는 호스트 OS와 미들웨어에만 초점을 맞추어 설명합니다.</p><h2 id="비행-콘트롤러-설정-파일-구조" tabindex="-1">비행 콘트롤러 설정 파일 구조 <a class="header-anchor" href="#비행-콘트롤러-설정-파일-구조" aria-label="Permalink to &quot;비행 콘트롤러 설정  파일 구조&quot;">​</a></h2><p>Board startup and configuration files are located under <a href="https://github.com/PX4/PX4-Autopilot/tree/main/boards/" target="_blank" rel="noreferrer">/boards</a> in each board&#39;s vendor-specific directory (i.e. <strong>boards/<em>VENDOR</em>/<em>MODEL</em>/</strong>).</p><p>예 FMUv5 :</p><ul><li>(All) Board-specific files: <a href="https://github.com/PX4/PX4-Autopilot/tree/main/boards/px4/fmu-v5" target="_blank" rel="noreferrer">/boards/px4/fmu-v5</a>.</li><li>Build configuration: <a href="https://github.com/PX4/PX4-Autopilot/blob/main/boards/px4/fmu-v5/default.px4board" target="_blank" rel="noreferrer">/boards/px4/fmu-v5/default.px4board</a>.</li><li>Board-specific initialisation file: <a href="https://github.com/PX4/PX4-Autopilot/blob/main/boards/px4/fmu-v5/init/rc.board_defaults" target="_blank" rel="noreferrer">/boards/px4/fmu-v5/init/rc.board_defaults</a><ul><li>A board-specific initialisation file is automatically included in startup scripts if found under the boards directory at <strong>init/rc.board</strong>.</li><li>이 파일은 특정 보드에만 존재하는 센서(및 기타 항목)를 시작하는 데 사용됩니다. 또한 보드의 기본 매개변수, UART 매핑 및 기타 특수한 경우를 설정하는 데 사용할 수 있습니다.</li><li>FMUv5은 시작되는 모든 Pixhawk 4 센서를 볼 수 있으며, 더 큰 LOGGER_BUF도 설정합니다.</li></ul></li></ul><h2 id="호스트-운영-체제-설정" tabindex="-1">호스트 운영 체제 설정 <a class="header-anchor" href="#호스트-운영-체제-설정" aria-label="Permalink to &quot;호스트 운영 체제 설정&quot;">​</a></h2><p>이 섹션에서는 지원되는 호스트 운영 체제에서 새 비행 콘트롤러 이식에 필요한 설정 파일의 목적과 위치에 대하여 설명합니다.</p><h3 id="nuttx" tabindex="-1">NuttX <a class="header-anchor" href="#nuttx" aria-label="Permalink to &quot;NuttX&quot;">​</a></h3><p>See <a href="./porting_guide_nuttx">NuttX Board Porting Guide</a>.</p><h3 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h3><p>Linux 보드에는 OS와 커널 설정이 포함되어 있지 않습니다. Linux에는 이미 보드에 사용할 수 있는 Linux 이미지에 의해 제공됩니다(즉시 관성 센서를 지원해야 함).</p><ul><li><a href="https://github.com/PX4/PX4-Autopilot/blob/main/boards/px4/raspberrypi/default.px4board" target="_blank" rel="noreferrer">boards/px4/raspberrypi/default.px4board</a> - RPi cross-compilation. </li></ul><h2 id="미들웨어-구성-요소-및-설정" tabindex="-1">미들웨어 구성 요소 및 설정 <a class="header-anchor" href="#미들웨어-구성-요소-및-설정" aria-label="Permalink to &quot;미들웨어 구성 요소 및 설정&quot;">​</a></h2><p>이 섹션에서는 다양한 미들웨어 구성 요소와 이를 새로운 비행 콘트롤러로 이식에 필요한 설정 파일 업데이트에 대하여 설명합니다.</p><h3 id="qurt-hexagon" tabindex="-1">QuRT / Hexagon <a class="header-anchor" href="#qurt-hexagon" aria-label="Permalink to &quot;QuRT / Hexagon&quot;">​</a></h3><ul><li>The start script is located in <a href="https://github.com/PX4/PX4-Autopilot/tree/main/posix-configs" target="_blank" rel="noreferrer">posix-configs/</a>. </li><li>OS 구성은 기본 Linux 이미지의 일부입니다(TODO: LINUX IMAGE 및 플래시 지침의 위치 제공).</li><li>The PX4 middleware configuration is located in <a href="https://github.com/PX4/PX4-Autopilot/tree/main/boards" target="_blank" rel="noreferrer">src/boards</a>. TODO: ADD BUS CONFIG</li></ul><h2 id="rc-uart-배선-권장-사항" tabindex="-1">RC UART 배선 권장 사항 <a class="header-anchor" href="#rc-uart-배선-권장-사항" aria-label="Permalink to &quot;RC UART 배선 권장 사항&quot;">​</a></h2><p>일반적으로 별도의 RX 및 TX 핀을 통해 RC를 마이크로 콘트롤러에 연결하는 것이 좋습니다. 그러나 RX와 TX가 함께 연결된 경우에는 UART의 경합 방지를 위하여, 단일 와이어 모드로 전환되어야 합니다. 이것은 보드 설정과 매니페스트 파일을 통하여 수행됩니다. One example is <a href="https://github.com/PX4/PX4-Autopilot/blob/main/boards/px4/fmu-v5/src/manifest.c" target="_blank" rel="noreferrer">px4fmu-v5</a>. </p><h2 id="getting-your-board-supported" tabindex="-1">Getting Your Board Supported <a class="header-anchor" href="#getting-your-board-supported" aria-label="Permalink to &quot;Getting Your Board Supported&quot;">​</a></h2><p>This page covers the <em>technical</em> work of porting PX4 to new hardware. The <em>process</em> for getting that port reviewed, merged, and listed on the PX4 website, including board IDs, USB VID/PID, flight-test evidence, and maintenance expectations, is documented separately:</p><ul><li><a href="./../hardware/board_support_guide">Manufacturer&#39;s PX4 Board Support Guide</a></li></ul><p>In short: build your own firmware target based on PX4, demonstrate stable flight on the current release, and open a pull request with your board support code, documentation, and flight logs. The board support guide explains each step.</p><p>The PX4 project supports and maintains the <a href="./../hardware/reference_design">FMU standard reference hardware</a> and any boards compatible with the standard, including the <a href="./../flight_controller/pixhawk_series">Pixhawk series</a> (see the <a href="./../flight_controller/">full list of supported hardware</a>). Boards merged into PX4 benefit from a port in the repository, firmware builds accessible from <em>QGroundControl</em>, compatibility with the rest of the ecosystem, and automated CI checks.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The cost of maintaining a port is proportional to how far it diverges from the standard. Consider that cost before deviating: staying close to the reference design lets you benefit from day-to-day PX4 development with minimal maintenance burden.</p></div><p>Manufacturers are responsible for keeping their port up to date and working across PX4 releases. The PX4 project reserves the right to refuse or remove ports that do not meet the project&#39;s requirements, and all contributors are expected to follow the <a href="https://github.com/PX4/PX4-Autopilot/blob/main/CODE_OF_CONDUCT.md" target="_blank" rel="noreferrer">Code of Conduct</a>.</p><h2 id="관련-정보" tabindex="-1">관련 정보 <a class="header-anchor" href="#관련-정보" aria-label="Permalink to &quot;관련 정보&quot;">​</a></h2><ul><li><a href="./../middleware/drivers">Device Drivers</a> - How to support new peripheral hardware (device drivers)</li><li><a href="./../dev_setup/building_px4">Building the Code</a> - How to build source and upload firmware</li><li>지원 비행 콘트롤러: <ul><li><a href="./../flight_controller/">Autopilot Hardware</a></li><li><a href="https://github.com/PX4/PX4-Autopilot/#supported-hardware" target="_blank" rel="noreferrer">Supported boards list</a> (Github) - Boards for which PX4-Autopilot has specific code</li></ul></li><li><a href="./../peripherals/">Supported Peripherals</a></li></ul>',31)])])}const f=r(i,[["render",l]]);export{c as __pageData,f as default};
